//! Asset pipeline sanity checks (design §4.6 item 2).
//!
//! `Explosion.wav` was lost from the original tree; it is regenerated by
//! `src/bin/cutwav.rs` from samples 0..=1830 of `MachineGun.wav`
//! (`Resources/Sounds/Explosion.txt`: `MachineGun.wav: 0-1830`) and
//! committed. This test pins its shape and content against the source
//! file so a future re-cut can't silently drift.

use std::path::Path;

fn assets_dir() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("assets")
}

#[test]
fn explosion_wav_is_1831_samples_cut_from_machine_gun_wav() {
    let machine_gun_path = assets_dir().join("Sounds/MachineGun.wav");
    let explosion_path = assets_dir().join("Sounds/Explosion.wav");

    let mut machine_gun = hound::WavReader::open(&machine_gun_path)
        .unwrap_or_else(|e| panic!("{}: {e}", machine_gun_path.display()));
    let mut explosion = hound::WavReader::open(&explosion_path)
        .unwrap_or_else(|e| panic!("{}: {e}", explosion_path.display()));

    assert_eq!(explosion.spec(), machine_gun.spec());

    let machine_gun_samples: Vec<i8> = machine_gun.samples::<i8>().map(|r| r.unwrap()).collect();
    let explosion_samples: Vec<i8> = explosion.samples::<i8>().map(|r| r.unwrap()).collect();

    assert_eq!(explosion_samples.len(), 1831, "expected samples 0..=1830 inclusive");
    assert_eq!(&explosion_samples[..], &machine_gun_samples[0..=1830]);
}

#[test]
fn shipped_bmps_and_wavs_exist() {
    let textures = assets_dir().join("Textures");
    for name in ["Camo big.bmp", "Screw.bmp", "Steel.bmp"] {
        assert!(textures.join(name).is_file(), "missing Textures/{name}");
    }
    let sounds = assets_dir().join("Sounds");
    for name in [
        "MachineGun.wav",
        "RocketLaunch.wav",
        "EditedRocketLaunch.wav",
        "Explosion.wav",
    ] {
        assert!(sounds.join(name).is_file(), "missing Sounds/{name}");
    }
}

#[test]
fn shipped_maze_files_reload_and_are_bordered() {
    for name in ["Small1.maz", "Small2.maz", "Small3.maz", "Small4.maz"] {
        let path = assets_dir().join("MazeFiles").join(name);
        let maze = operation_purge::maze::Maze::load(&path)
            .unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        for x in 0..maze.cx {
            assert!(maze.surrounding_walls(x, 0)[0], "{name}: top border missing at x={x}");
            assert!(
                maze.surrounding_walls(x, maze.cy - 1)[1],
                "{name}: bottom border missing at x={x}"
            );
        }
        for y in 0..maze.cy {
            assert!(
                maze.surrounding_walls(0, y)[2],
                "{name}: left border missing at y={y}"
            );
            assert!(
                maze.surrounding_walls(maze.cx - 1, y)[3],
                "{name}: right border missing at y={y}"
            );
        }
    }
}

/// Every quoted string in `GameData.toml` ending in a known asset extension.
/// A plain text scan (not a TOML parse) so it is immune to toml-crate API
/// quirks and catches the filename literals wherever they appear. Asset
/// filenames contain no escaped quotes, so splitting on `"` and taking the
/// quoted (odd-index) segments is exact.
fn gamedata_asset_refs() -> Vec<String> {
    let text = std::fs::read_to_string(assets_dir().join("GameData.toml"))
        .expect("assets/GameData.toml must be readable");
    let mut refs: Vec<String> = text
        .lines()
        .flat_map(|line| line.split('"').skip(1).step_by(2))
        .filter(|s| {
            let l = s.to_ascii_lowercase();
            l.ends_with(".wav") || l.ends_with(".bmp") || l.ends_with(".png")
        })
        .map(|s| s.to_string())
        .collect();
    refs.sort();
    refs.dedup();
    refs
}

/// Regression guard (the bug the M1 conversion left behind): every sound and
/// texture named in the shipped `GameData.toml` must exist on disk, or the
/// game logs "could not preload ..." at startup. Sounds live under `Sounds/`,
/// image textures under `Textures/`.
#[test]
fn every_gamedata_asset_reference_exists_on_disk() {
    let refs = gamedata_asset_refs();
    assert!(!refs.is_empty(), "expected GameData.toml to reference some assets");

    let sounds = assets_dir().join("Sounds");
    let textures = assets_dir().join("Textures");
    let missing: Vec<&String> = refs
        .iter()
        .filter(|name| {
            let is_wav = name.to_ascii_lowercase().ends_with(".wav");
            let dir = if is_wav { &sounds } else { &textures };
            !dir.join(name).is_file()
        })
        .collect();
    assert!(missing.is_empty(), "GameData.toml references missing assets: {missing:?}");
}

#[test]
fn generated_alarm_wavs_match_the_surviving_format() {
    // Alarm.wav / FastAlarm.wav are reconstructed by `gen_alarms` (the
    // originals were lost); they must decode in the same 8-bit mono 22050 Hz
    // path as the surviving WAVs so the loader treats them identically.
    let reference = hound::WavReader::open(assets_dir().join("Sounds/MachineGun.wav"))
        .unwrap()
        .spec();
    for name in ["Alarm.wav", "FastAlarm.wav"] {
        let path = assets_dir().join("Sounds").join(name);
        let reader =
            hound::WavReader::open(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        assert_eq!(reader.spec(), reference, "{name} format must match MachineGun.wav");
    }
}

#[test]
fn liberation_sans_bold_font_is_present_and_loadable() {
    let path = assets_dir().join("Fonts/LiberationSans-Bold.ttf");
    let data = std::fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    ab_glyph::FontRef::try_from_slice(&data).expect("must parse as a valid font");
}
